   109	    private func handleData(_ data: Data) {
   110	        queue.sync { buffer.append(data) }
   111	
   112	        while true {
   113	            let lineData: Data? = queue.sync {
   114	                guard let idx = buffer.firstIndex(of: UInt8(ascii: "\n")) else { return nil }
   115	                let line = Data(buffer[..<idx])
   116	                buffer = buffer[(idx + 1)...]
   117	                return line
   118	            }
   119	            guard let data = lineData,
   120	                  let line = String(data: data, encoding: .utf8),
   121	                  !line.isEmpty else { break }
   122	            processMessage(line)
   123	        }
   124	    }
