   126	    private func processMessage(_ json: String) {
   127	        guard let data = json.data(using: .utf8) else { return }
   128	
   129	        // Try as incoming request from agent (bidirectional: has method + id)
   130	        if let dict = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
   131	           let method = dict["method"] as? String,
   132	           let reqId = dict["id"] {
   133	            let idString = "\(reqId)"  // Handle both Int and String IDs
   134	            handleIncomingRequest(id: idString, method: method, params: dict["params"] as? [String: Any])
   135	            return
   136	        }
   137	
   138	        // Try as notification (has method, no id)
   139	        if let notification = try? JSONDecoder().decode(JsonRpcNotification.self, from: data),
   140	           ACPProtocolAdapter.isSessionUpdateMethod(notification.method) {
   141	            handleSessionUpdate(notification.params)
   142	            return
   143	        }
   144	
   145	        // Try as response to our request
   146	        if let response = try? JSONDecoder().decode(JsonRpcResponse.self, from: data),
   147	           let reqId = response.id {
   148	            let handler = queue.sync { pendingRequests.removeValue(forKey: reqId) }
   149	            if let handler = handler {
   150	                if let error = response.error {
   151	                    let nsError = NSError(
   152	                        domain: "ACP", code: error.code,
   153	                        userInfo: [NSLocalizedDescriptionKey: error.message]
   154	                    )
   155	                    handler(.failure(nsError))
   156	                } else {
   157	                    handler(.success(response.result))
   158	                }
   159	            }
   160	        }
   161	    }
