   220	    private func handleSessionUpdate(_ params: [String: AnyCodable]?) {
   221	        guard let update = params?["update"]?.dictValue,
   222	              let rawKind = update["sessionUpdate"]?.stringValue ?? update["type"]?.stringValue,
   223	              let kind = ACPProtocolAdapter.parseUpdateKind(rawKind) else { return }
   224	
   225	        switch kind {
   226	        case .agentMessageChunk:
   227	            if let content = update["content"]?.dictValue,
   228	               let text = content["text"]?.stringValue {
   229	                onUpdate?(text)
   230	            } else if let text = update["text"]?.stringValue {
   231	                onUpdate?(text)
   232	            }
   233	
   234	        case .toolCall:
   235	            if let toolCallId = update["toolCallId"]?.stringValue,
   236	               let title = update["title"]?.stringValue {
   237	                let toolKind = update["kind"]?.stringValue ?? "other"
   238	                let status = update["status"]?.stringValue ?? "pending"
   239	                let call = ACPToolCall(id: toolCallId, title: title, kind: toolKind, status: status)
   240	                // Capture diff content if present
   241	                if let content = update["content"]?.arrayValue,
   242	                   let first = content.first?.dictValue,
   243	                   first["type"]?.stringValue == "diff",
   244	                   let path = first["path"]?.stringValue,
   245	                   let oldText = first["oldText"]?.stringValue,
   246	                   let newText = first["newText"]?.stringValue {
   247	                    self.lastToolCallDiff[toolCallId] = DiffContent(oldText: oldText, newText: newText, path: path)
   248	                }
   249	                let locationPaths = Self.locationPaths(from: update)
   250	                if !locationPaths.isEmpty {
   251	                    self.lastToolCallLocations[toolCallId] = locationPaths
   252	                }
   253	                toolCalls.append(call)
   254	                onToolCall?(call)
   255	            }
   256	
   257	        case .toolCallUpdate:
   258	            if let toolCallId = update["toolCallId"]?.stringValue {
   259	                let status = update["status"]?.stringValue ?? "in_progress"
   260	                let updateLocationPaths = Self.locationPaths(from: update)
   261	                if !updateLocationPaths.isEmpty {
   262	                    let previousPaths = lastToolCallLocations[toolCallId] ?? []
   263	                    lastToolCallLocations[toolCallId] = Self.mergeUniquePaths(
   264	                        previousPaths + updateLocationPaths
   265	                    )
   266	                }
   267	                if let idx = toolCalls.firstIndex(where: { $0.id == toolCallId }) {
   268	                    toolCalls[idx].status = status
   269	                }
   270	                onToolCallUpdate?(toolCallId, status)
   271	
   272	                let toolKind = update["kind"]?.stringValue
   273	                    ?? toolCalls.first(where: { $0.id == toolCallId })?.kind
   274	                    ?? "other"
   275	                if status == "completed", toolKind == "edit" {
   276	                    let locationPaths = lastToolCallLocations[toolCallId] ?? updateLocationPaths
   277	                    if !locationPaths.isEmpty {
   278	                        onEditToolCompleted?(toolCallId, locationPaths)
   279	                    }
   280	                }
   281	
   282	                let isTerminalStatus = status == "completed"
   283	                    || status == "failed"
   284	                    || status == "cancelled"
   285	                if isTerminalStatus {
   286	                    lastToolCallLocations.removeValue(forKey: toolCallId)
   287	                    lastToolCallDiff.removeValue(forKey: toolCallId)
   288	                    if pendingPermission?.toolCallId == toolCallId {
