   299	    nonisolated static func locationPaths(from update: [String: AnyCodable]) -> [String] {
   300	        guard let locations = update["locations"]?.arrayValue else { return [] }
   301	        var parsedPaths: [String] = []
   302	        var seenPaths: Set<String> = []
   303	        for locationEntry in locations {
   304	            guard let locationDict = locationEntry.dictValue,
   305	                  let filePath = locationDict["path"]?.stringValue,
   306	                  !filePath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { continue }
   307	            if seenPaths.insert(filePath).inserted {
   308	                parsedPaths.append(filePath)
   309	            }
   310	        }
   311	        return parsedPaths
   312	    }
