   393	    private func encodeAnyCodable(_ value: AnyCodable) -> Any {
   394	        switch value.value {
   395	        case let str as String: return str
   396	        case let int as Int: return int
   397	        case let dbl as Double: return dbl
   398	        case let bool as Bool: return bool
   399	        case let dict as [String: AnyCodable]:
   400	            return dict.mapValues { encodeAnyCodable($0) }
   401	        case let arr as [AnyCodable]:
   402	            return arr.map { encodeAnyCodable($0) }
   403	        default: return NSNull()
   404	        }
   405	    }
