   212	    private func runFileTreeScan(for workspace: URL) {
   213	        guard fileTreeRescanRequested else { return }
   214	        isFileTreeScanRunning = true
   215	        fileTreeRescanRequested = false
   216	        let scanID = UUID()
   217	        activeFileTreeScanID = scanID
   218	
   219	        fileTreeLoadTask?.cancel()
   220	        fileTreeLoadTask = Task(priority: .userInitiated) { [weak self] in
   221	            let scanResult = await Self.scanWorkspace(at: workspace)
   222	            guard !Task.isCancelled else { return }
   223	            await MainActor.run {
   224	                guard let self = self else { return }
   225	                guard Self.shouldApplyFileTreeScanResult(
   226	                    activeScanID: self.activeFileTreeScanID,
   227	                    scanID: scanID,
   228	                    currentWorkspace: self.workspace,
   229	                    scanWorkspace: workspace
   230	                ) else {
   231	                    if self.activeFileTreeScanID == scanID {
   232	                        self.isFileTreeScanRunning = false
   233	                        self.fileTreeRescanRequested = false
   234	                    }
   235	                    return
   236	                }
   237	                self.applyScanResult(scanResult, workspace: workspace)
   238	                self.isFileTreeScanRunning = false
   239	                if self.fileTreeRescanRequested {
   240	                    self.runFileTreeScan(for: workspace)
   241	                }
   242	            }
   243	        }
   244	    }
