   488	    func save() {
   489	        guard currentIndex >= 0 && currentIndex < openFiles.count else { return }
   490	        let doc = openFiles[currentIndex]
   491	        try? doc.save(doc.content)
   492	
   493	        // Rename Untitled files based on first line
