   498	                loadFileTree()
   499	            }
   500	        }
   501	        openFiles[currentIndex].isDirty = false
   502	
   503	        // Incremental index updates after save
   504	        let savedContent = openFiles[currentIndex].content.string
   505	        let savedURL = openFiles[currentIndex].url
   506	        noteIndex.updateFile(savedURL, content: savedContent)
   507	        backlinkIndex.updateFile(savedURL, content: savedContent)
