   567	    private func renamedURL(for doc: Document) -> URL? {
   568	        let firstLine = doc.content.string.components(separatedBy: "\n").first ?? ""
   569	        let cleaned = firstLine
   570	            .trimmingCharacters(in: .whitespaces)
   571	            .replacingOccurrences(of: "#", with: "")
   572	            .trimmingCharacters(in: .whitespaces)
   573	            .prefix(50)
   574	        guard !cleaned.isEmpty else { return nil }
   575	        let safeName = String(cleaned).replacingOccurrences(of: "/", with: "-")
   576	        let ext = doc.url.pathExtension
   577	        let newURL = doc.url.deletingLastPathComponent()
   578	            .appendingPathComponent("\(safeName).\(ext)")
   579	        guard !FileManager.default.fileExists(atPath: newURL.path) else { return nil }
   580	        return newURL
   581	    }
