   587	    private static func equivalentFileURL(_ firstURL: URL, _ secondURL: URL) -> Bool {
   588	        if firstURL.standardizedFileURL.path == secondURL.standardizedFileURL.path {
   589	            return true
   590	        }
   591	        return canonicalFileURL(firstURL).path == canonicalFileURL(secondURL).path
   592	    }
