   603	    private func removeFileFromInMemoryTree(_ fileURL: URL) {
   604	        fileTree = Self.removingNode(fileURL, from: fileTree)
   605	    }
   606	
   607	    func addFileToInMemoryTree(_ fileURL: URL) {
   608	        guard let workspace else { return }
   609	        let relativePath = fileURL.path.replacingOccurrences(
   610	            of: workspace.path + "/", with: ""
   611	        )
   612	        let components = relativePath.split(separator: "/").map(String.init)
   613	        guard !components.isEmpty else { return }
   614	        fileTree = Self.insertingNode(fileURL, path: components, into: fileTree)
   615	    }
   616	
   617	    private static func insertingNode(
   618	        _ target: URL,
   619	        path: [String],
   620	        into nodes: [FileTreeNode]
   621	    ) -> [FileTreeNode] {
   622	        guard let first = path.first else { return nodes }
   623	        let rest = Array(path.dropFirst())
   624	
   625	        for (index, node) in nodes.enumerated() where node.url.lastPathComponent == first {
   626	            if rest.isEmpty {
   627	                return nodes // Already exists
   628	            }
   629	            if node.isDirectory, let children = node.children {
   630	                var updated = nodes
   631	                updated[index] = FileTreeNode(
   632	                    url: node.url,
   633	                    isDirectory: true,
   634	                    children: insertingNode(target, path: rest, into: children)
   635	                )
   636	                return updated
   637	            }
   638	            return nodes
   639	        }
   640	
   641	        // Not found — add new node
   642	        if rest.isEmpty {
   643	            let newNode = FileTreeNode(url: target, isDirectory: false, children: nil)
   644	            return (nodes + [newNode]).sorted { $0.url.lastPathComponent < $1.url.lastPathComponent }
   645	        }
   646	        return nodes
   647	    }
   648	
   649	    private static func removingNode(_ target: URL, from nodes: [FileTreeNode]) -> [FileTreeNode] {
   650	        nodes.compactMap { node in
   651	            if equivalentFileURL(node.url, target) {
   652	                return nil
   653	            }
   654	
   655	            if node.isDirectory, let children = node.children {
   656	                let prunedChildren = removingNode(target, from: children)
   657	                return FileTreeNode(url: node.url, isDirectory: true, children: prunedChildren)
   658	            }
   659	
   660	            return node
   661	        }
   662	    }
