   694	    func closeTab(at index: Int) {
   695	        guard index >= 0 && index < openFiles.count else { return }
   696	        let url = openFiles[index].url
   697	
   698	        // Clean up chat state for this tab
   699	        chatStates[url]?.stop()
   700	        chatStates.removeValue(forKey: url)
   701	        chatVisibleTabs.remove(url)
   702	
   703	        openFiles.remove(at: index)
   704	        if openFiles.isEmpty {
   705	            currentIndex = -1
   706	        } else if currentIndex == index {
