   277	        let mediaFilenames = Set(mediaFiles.map { $0.lastPathComponent })
   278	
   279	        // Single pass: collect all referenced media filenames from markdown files
   280	        var referencedFilenames: Set<String> = []
   281	        let enumerator = FileManager.default.enumerator(
   282	            at: workspace,
   283	            includingPropertiesForKeys: [.isDirectoryKey],
   284	            options: [.skipsHiddenFiles]
   285	        )
   286	        while let fileURL = enumerator?.nextObject() as? URL {
   287	            guard fileURL.pathExtension == "md" else { continue }
   288	            guard let content = try? String(contentsOf: fileURL, encoding: .utf8) else { continue }
   289	            // Check which media files are referenced in this content
   290	            for filename in mediaFilenames where content.contains(filename) {
   291	                referencedFilenames.insert(filename)
   292	            }
   293	            // Early exit if all media files are referenced
   294	            if referencedFilenames.count == mediaFilenames.count {
   295	                break
   296	            }
   297	        }
   298	
   299	        // Delete unreferenced media files
   300	        var removed: Set<URL> = []
   301	        for mediaURL in mediaFiles {
   302	            let filename = mediaURL.lastPathComponent
   303	            if !referencedFilenames.contains(filename) {
   304	                try? FileManager.default.trashItem(at: mediaURL, resultingItemURL: nil)
   305	                removed.insert(mediaURL)
   306	            }
   307	        }
   308	        return removed
   309	    }
