   488	    func save() {
   489	        guard currentIndex >= 0 && currentIndex < openFiles.count else { return }
   490	        let doc = openFiles[currentIndex]
   491	        try? doc.save(doc.content)
   492	
   493	        // Rename Untitled files based on first line
   494	        if doc.url.lastPathComponent.hasPrefix("Untitled") {
   495	            if let newURL = renamedURL(for: doc) {
   496	                try? FileManager.default.moveItem(at: doc.url, to: newURL)
   497	                openFiles[currentIndex] = Document(url: newURL, content: doc.content)
   498	                loadFileTree()
   499	            }
   500	        }
   501	        openFiles[currentIndex].isDirty = false
   502	
   503	        // Incremental index updates after save
   504	        let savedContent = openFiles[currentIndex].content.string
   505	        let savedURL = openFiles[currentIndex].url
   506	        noteIndex.updateFile(savedURL, content: savedContent)
   507	        backlinkIndex.updateFile(savedURL, content: savedContent)
