   512	    func saveAll() {
   513	        // Collect documents to save on main thread
   514	        var docsToSave: [(url: URL, content: String, isDocx: Bool, index: Int)] = []
   515	        var renameOps: [(index: Int, oldURL: URL, newURL: URL)] = []
   516	
   517	        for index in openFiles.indices where openFiles[index].isDirty {
   518	            let doc = openFiles[index]
   519	            let isDocx = doc.url.pathExtension.lowercased() == "docx"
   520	
   521	            // For docx, save synchronously (needs attributed string)
   522	            if isDocx {
   523	                try? doc.save(doc.content)
   524	            } else {
   525	                docsToSave.append((doc.url, doc.content.string, isDocx, index))
   526	            }
   527	
   528	            // Check for rename
   529	            if doc.url.lastPathComponent.hasPrefix("Untitled"),
   530	               let newURL = renamedURL(for: doc) {
   531	                renameOps.append((index, doc.url, newURL))
   532	            }
   533	
   534	            openFiles[index].isDirty = false
   535	
   536	            // Update indexes on main thread
   537	            let savedURL = openFiles[index].url
   538	            let savedContent = openFiles[index].content.string
   539	            noteIndex.updateFile(savedURL, content: savedContent)
   540	            backlinkIndex.updateFile(savedURL, content: savedContent)
   541	            tagIndex.updateFile(savedURL, content: savedContent)
   542	            peopleIndex.updateFile(savedURL, content: savedContent)
   543	        }
   544	
   545	        // Background save for plain text files
   546	        if !docsToSave.isEmpty {
   547	            saveQueue.cancelAllOperations()
   548	            let operation = BlockOperation { [docsToSave] in
   549	                for doc in docsToSave {
   550	                    try? doc.content.write(to: doc.url, atomically: true, encoding: .utf8)
   551	                }
   552	            }
   553	            saveQueue.addOperation(operation)
   554	        }
   555	
   556	        // Handle renames on main thread
   557	        for rename in renameOps {
   558	            try? FileManager.default.moveItem(at: rename.oldURL, to: rename.newURL)
   559	            let content = openFiles[rename.index].content
   560	            openFiles[rename.index] = Document(url: rename.newURL, content: content)
   561	        }
   562	        if !renameOps.isEmpty { loadFileTree() }
   563	
   564	        dailyNoteManager.saveAll()
   565	    }
