   594	    private static func deletionCandidates(for url: URL) -> [URL] {
   595	        let standardized = url.standardizedFileURL
   596	        let canonical = canonicalFileURL(url)
   597	        if standardized.path == canonical.path {
   598	            return [standardized]
   599	        }
   600	        return [standardized, canonical]
   601	    }
