   666	        pendingFileTreeReloadTask = Task { @MainActor [weak self] in
   667	            try? await Task.sleep(nanoseconds: UInt64(delaySeconds * 1_000_000_000))
   668	            guard !Task.isCancelled else { return }
   669	            self?.loadFileTree()
   670	        }
   671	    }
