   805	    @discardableResult
   806	    func delete(_ url: URL) -> Bool {
   807	        let candidates = Self.deletionCandidates(for: url)
   808	
   809	        // Close if open (canonical path match prevents stale tabs)
   810	        if let idx = openFiles.firstIndex(
   811	            where: { openFile in
   812	                candidates.contains { Self.equivalentFileURL(openFile.url, $0) }
   813	            }
   814	        ) {
   815	            closeTab(at: idx)
   816	        }
   817	
   818	        switch deleteFromDisk(url, scope: .workspace) {
   819	        case .deleted(let deletedURL):
   820	            resetFileTreeScanState()
   821	            removeFileFromInMemoryTree(deletedURL)
   822	            rebuildIndexesFromCurrentTree()
   823	            scheduleFileTreeReload(delaySeconds: 0.6)
   824	            return true
   825	        case .notFound:
   826	            resetFileTreeScanState()
   827	            removeFileFromInMemoryTree(url)
   828	            rebuildIndexesFromCurrentTree()
   829	            scheduleFileTreeReload(delaySeconds: 0.6)
   830	            return false
   831	        case .failed(let message):
   832	            print("[DocumentStore] Failed to delete \(url.path): \(message)")
   833	            return false
   834	        }
   835	    }
