   872	    func confirmRename() {
   873	        guard let url = renameTarget else { return }
   874	        let newName = renameText.trimmingCharacters(in: .whitespaces)
   875	        guard !newName.isEmpty, newName != url.lastPathComponent else {
   876	            renameTarget = nil
   877	            return
   878	        }
   879	        let newURL = url.deletingLastPathComponent().appendingPathComponent(newName)
   880	        do {
